    ["青蛙王子锁血-二转三33%"] = "Принц-лягушка запирает кровь – два на три 33%",
    ["靠近选项，点击“抓取文字”技能抓取；返回句子，点击\"E\"填入词语"] = "Подойдите к опциям и нажмите навык «Захватить текст», чтобы захватить его; вернитесь к предложению и нажмите «E», чтобы заполнить слова",
    ["额外提升目标10%减伤，持续6秒。"] = "Увеличивает снижение урона цели еще на 10% на 6 секунд.",
    ["风刃空间裂隙2"] = "Космический разлом лезвия ветра 2",
    ["魔法少女"] = "волшебная девочка",
